import {giftContentPages} from './experience.js';
import {createPaper} from './paper.js';
// Store-only ZIP: PNG images are already compressed. UTF-8 filenames, CRC32 checksums.
const encoder=new TextEncoder(),crcTable=Uint32Array.from({length:256},(_,n)=>{let c=n;for(let i=0;i<8;i++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0;});
function crc32(bytes){let c=0xffffffff;for(const byte of bytes)c=crcTable[(c^byte)&255]^(c>>>8);return (c^0xffffffff)>>>0;}
function header(size,values){const bytes=new Uint8Array(size),view=new DataView(bytes.buffer);for(const [offset,value,width] of values)width===2?view.setUint16(offset,value,true):view.setUint32(offset,value,true);return bytes;}
export function makeKeepsakeArchive(files){const local=[],central=[];let offset=0,centralSize=0;for(const file of files){const name=encoder.encode(file.name),data=file.bytes,crc=crc32(data),entry=header(30,[[0,0x04034b50,4],[4,20,2],[6,0x800,2],[12,33,2],[14,crc,4],[18,data.length,4],[22,data.length,4],[26,name.length,2]]);local.push(entry,name,data);const record=header(46,[[0,0x02014b50,4],[4,20,2],[6,20,2],[8,0x800,2],[14,33,2],[16,crc,4],[20,data.length,4],[24,data.length,4],[28,name.length,2],[42,offset,4]]);central.push(record,name);offset+=entry.length+name.length+data.length;centralSize+=record.length+name.length;}const end=header(22,[[0,0x06054b50,4],[8,files.length,2],[10,files.length,2],[12,centralSize,4],[16,offset,4]]);return new Blob([...local,...central,end],{type:'application/zip'});}
export function initKeepsake({getData,onPreview,toast,authorize=async()=>true}){
 const button=document.createElement('button');button.type='button';button.className='review-keepsake';button.textContent='Revisar e guardar meu mimo';document.querySelector('#recipient-preview').after(button);
 const dialog=document.createElement('dialog');dialog.className='keepsake-dialog';dialog.setAttribute('aria-labelledby','keepsake-title');dialog.innerHTML='<button class="keepsake-close" aria-label="Voltar à edição">×</button><p class="keepsake-eyebrow">O cuidado está nos detalhes</p><h2 id="keepsake-title">Pronto para guardar?</h2><p class="keepsake-description">Confira o que você preparou. Você pode voltar e mudar qualquer detalhe.</p><dl class="keepsake-summary"></dl><p class="keepsake-warning" role="status"></p><button class="button primary keepsake-preview">Ver pelos olhos de quem recebe</button><button class="button outline keepsake-download">Baixar uma cópia das páginas</button><p class="keepsake-local">A cópia contém imagens PNG da capa e do conteúdo, além das fotos que você adicionou. O envio por link e o pagamento serão ativados em outra etapa.</p><p class="keepsake-progress" role="status"></p>';document.body.append(dialog);
 function open(){const data=getData(),summary=dialog.querySelector('dl');summary.replaceChildren();dialog.querySelector('.keepsake-download').textContent=data.format==='livro'?'Baixar capa e páginas':'Baixar capa e parte interna';const rows=[['Para',data.recipient||'Nome ainda não preenchido'],['Formato',({stories:'Stories de memórias',livro:'Livro de memórias',cartao:'Cartão de carinho',convite:'Convite personalizado'})[data.format]],['Conteúdo',data.format==='livro'?giftContentPages(data).length+' páginas de conteúdo':data.format==='cartao'?'Capa e uma dedicatória interna · abre e fecha':data.format==='convite'?[data.eventDate?new Date(data.eventDate+'T12:00:00').toLocaleDateString('pt-BR'):'Data a preencher',data.eventPlace||'Local a preencher'].join(' · '):'Uma mensagem e '+(data.photos?.length??0)+' fotos'],['Acabamento',({algodao:'Algodão',linho:'Linho',kraft:'Kraft'})[data.texture]]];for(const [name,value] of rows){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=value;summary.append(dt,dd);}const blank=data.format==='livro'?data.pages?.filter(page=>!page.message.trim()).length:!data.message.trim();dialog.querySelector('.keepsake-warning').textContent=!data.recipient.trim()?'Falta escrever para quem é este mimo. Você ainda pode baixar uma prévia.':blank?'Há páginas sem mensagem. Vale conferir antes de guardar.':'Seu mimo está personalizado. Confira a abertura e guarde uma cópia.';dialog.showModal();}
 button.addEventListener('click',open);dialog.querySelector('.keepsake-close').addEventListener('click',()=>dialog.close());dialog.querySelector('.keepsake-preview').addEventListener('click',()=>{dialog.close();onPreview();});
 let busy=false;dialog.querySelector('.keepsake-download').addEventListener('click',async()=>{if(busy||!await authorize())return;busy=true;const download=dialog.querySelector('.keepsake-download'),progress=dialog.querySelector('.keepsake-progress');download.disabled=true;const data=getData(),mount=document.createElement('div');mount.style.cssText='position:fixed;left:-10000px;top:0;width:1400px;height:1000px;pointer-events:none';mount.setAttribute('aria-hidden','true');document.body.append(mount);let renderer;
  try{renderer=createPaper(mount,data);const files=[];async function add(name){const uri=await renderer.exportPNG(),bytes=new Uint8Array(await (await fetch(uri)).arrayBuffer());files.push({name,bytes});}
   progress.textContent='Preparando a capa…';renderer.open(false);await add('capimimo/capa.png');const pages=giftContentPages(data);
   for(let i=0;i<pages.length;i++){progress.textContent='Preparando página '+(i+1)+' de '+pages.length+'…';renderer.set({...data,pageTitle:pages[i].title,message:pages[i].message,photo:pages[i].photo});renderer.open(true);await add('capimimo/pagina-'+String(i+1).padStart(2,'0')+'.png');}
   for(let i=0;i<(data.photos?.length??0);i++){const bytes=new Uint8Array(await (await fetch(data.photos[i].src)).arrayBuffer());files.push({name:'capimimo/fotos/foto-'+String(i+1).padStart(2,'0')+'.jpg',bytes});}
   files.push({name:'capimimo/LEIA-ME.txt',bytes:encoder.encode('Capimimo — uma lembrança para guardar.\nEstas imagens são uma cópia local da capa e de cada página.\nSeu presente continua editável neste navegador.\n')});const blob=makeKeepsakeArchive(files),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='capimimo-'+data.format+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);progress.textContent='Cópia pronta. Confira o arquivo nos downloads do navegador.';toast('Suas páginas estão prontas para guardar.');
  }catch{progress.textContent='Não foi possível preparar a cópia agora. Suas escolhas continuam no editor. Tente novamente.';}finally{renderer?.destroy();mount.remove();busy=false;download.disabled=false;}
 });return {open};
}
